class Solution:
    def search(self, nums: List[int], target: int) -> int:
        lo, hi = 0, len(nums) - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if nums[mid] == target:  # viz:mid
                return mid  # viz:found
            if nums[mid] < target:
                lo = mid + 1  # viz:right
            else:
                hi = mid - 1  # viz:left
        return -1  # viz:missing
